// ============================================
// Configuratie — pas deze waarden aan!
// ============================================
const ODOO_URL = 'https://jouw-odoo-url.com';
const ODOO_DB = 'jouw-database';
const ODOO_USER = 'admin';
const ODOO_PASSWORD = 'jouw-api-key';

const input = $input.first().json;

// Sla config + input op voor gebruik in volgende nodes
return [{
  json: {
    config: { url: ODOO_URL, db: ODOO_DB, user: ODOO_USER, password: ODOO_PASSWORD },
    input: input,
    rpc: {
      jsonrpc: '2.0',
      id: 1,
      method: 'call',
      params: {
        service: 'common',
        method: 'authenticate',
        args: [ODOO_DB, ODOO_USER, ODOO_PASSWORD, {}]
      }
    }
  }
}];

// Haal uid op uit auth response
const authResponse = $input.first().json;
const uid = authResponse.result;
if (!uid) throw new Error('Odoo authenticatie mislukt!');

// Haal originele input op via $('Setup') referentie
const setup = $('Setup').first().json;
const config = setup.config;
const input = setup.input;
const projectId = input.project_id;
const gebouwen = input.gebouwen || [];

// Maak platte lijst van alle taken in volgorde:
// 1. Eerst alle gebouwen
// 2. Dan alle verdiepen (met referentie naar parent gebouw)
// 3. Dan alle collectoren
// 4. Dan alle kringen
const tasks = [];

for (let gi = 0; gi < gebouwen.length; gi++) {
  const g = gebouwen[gi];
  tasks.push({
    ref: `g_${gi}`,
    parentRef: null,
    level: 'gebouw',
    stageName: 'Blokken',
    odooId: g.odoo_id ? parseInt(g.odoo_id) : null,
    values: { name: g.naam, project_id: projectId, parent_id: false },
    meta: { gi, naam: g.naam }
  });

  for (let vi = 0; vi < (g.verdiepen || []).length; vi++) {
    const v = g.verdiepen[vi];
    tasks.push({
      ref: `v_${gi}_${vi}`,
      parentRef: `g_${gi}`,
      level: 'verdiep',
      stageName: 'Verdiepen',
      odooId: v.odoo_id ? parseInt(v.odoo_id) : null,
      values: { name: `Verdieping ${v.nummer}`, project_id: projectId },
      meta: { gi, vi, nummer: v.nummer }
    });

    for (let ci = 0; ci < (v.collectoren || []).length; ci++) {
      const c = v.collectoren[ci];
      tasks.push({
        ref: `c_${gi}_${vi}_${ci}`,
        parentRef: `v_${gi}_${vi}`,
        level: 'collector',
        stageName: 'Collectoren',
        odooId: c.odoo_id ? parseInt(c.odoo_id) : null,
        values: { name: c.naam || `Collector ${c.nummer}`, project_id: projectId },
        meta: { gi, vi, ci, nummer: c.nummer }
      });

      for (let ki = 0; ki < (c.kringen || []).length; ki++) {
        const k = c.kringen[ki];
        tasks.push({
          ref: `k_${gi}_${vi}_${ci}_${ki}`,
          parentRef: `c_${gi}_${vi}_${ci}`,
          level: 'kring',
          stageName: 'Kringen',
          odooId: k.odoo_id ? parseInt(k.odoo_id) : null,
          values: { name: `Kring ${k.nummer}`, project_id: projectId },
          meta: { gi, vi, ci, ki, nummer: k.nummer }
        });
      }
    }
  }
}

// Geef elke taak mee als apart item + gedeelde context
return tasks.map(task => ({
  json: {
    config,
    uid,
    projectId,
    task,
    idMap: {},      // wordt gevuld tijdens de loop
    stageMap: {}    // wordt gevuld tijdens de loop
  }
}));

// Bouw het JSON-RPC request voor de huidige taak
const item = $input.first().json;
const { config, uid, task } = item;

// Haal idMap en stageMap op uit workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.idMap) staticData.idMap = {};
if (!staticData.stageMap) staticData.stageMap = {};

const idMap = staticData.idMap;
const stageMap = staticData.stageMap;

// Stap 1: Kijk of we al een stage_id hebben, anders eerst opzoeken
if (task.stageName && !stageMap[task.stageName]) {
  // Geef een stage-lookup request terug
  return [{
    json: {
      step: 'stage_lookup',
      config,
      uid,
      task,
      rpc: {
        jsonrpc: '2.0',
        id: Date.now(),
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            config.db, uid, config.password,
            'project.task.type', 'search',
            [[['name', '=', task.stageName]]]
          ]
        }
      }
    }
  }];
}

// Stap 2: Bouw het create/write request
const values = { ...task.values };

// Voeg stage_id toe
if (task.stageName && stageMap[task.stageName]) {
  values.stage_id = stageMap[task.stageName];
}

// Voeg parent_id toe (opzoeken uit idMap)
if (task.parentRef && idMap[task.parentRef]) {
  values.parent_id = idMap[task.parentRef];
}

let rpc;
if (task.odooId) {
  // Update bestaand record
  rpc = {
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [config.db, uid, config.password, 'project.task', 'write', [[task.odooId], values]]
    }
  };
} else {
  // Nieuw record
  rpc = {
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [config.db, uid, config.password, 'project.task', 'create', [values]]
    }
  };
}

return [{
  json: {
    step: 'save',
    config,
    uid,
    task,
    rpc
  }
}];

// Verwerk het Odoo response en sla IDs op
const response = $input.first().json;
const buildRequest = $('Build Request').first().json;
const { step, task } = buildRequest;

const staticData = $getWorkflowStaticData('global');
if (!staticData.idMap) staticData.idMap = {};
if (!staticData.stageMap) staticData.stageMap = {};
if (!staticData.results) staticData.results = [];

if (response.error) {
  throw new Error(
    `Odoo fout bij ${task.ref}: ` +
    (response.error.data?.message || response.error.message || JSON.stringify(response.error))
  );
}

if (step === 'stage_lookup') {
  // Sla stage ID op
  const stageIds = response.result;
  if (stageIds && stageIds.length > 0) {
    staticData.stageMap[task.stageName] = stageIds[0];
  }
  // We moeten deze taak OPNIEUW verwerken (nu met stage_id)
  // Stuur het item terug met een flag
  return [{ json: { needsReprocess: true, task } }];
}

if (step === 'save') {
  const odooId = task.odooId || response.result;
  // Sla het ID op zodat kinderen het kunnen gebruiken
  staticData.idMap[task.ref] = odooId;
  // Sla resultaat op voor de eindresponse
  staticData.results.push({
    ref: task.ref,
    parentRef: task.parentRef,
    level: task.level,
    odooId: odooId,
    meta: task.meta
  });
}

return [{ json: { done: true, ref: task.ref } }];

// Bouw het geneste resultaat op uit de opgeslagen resultaten
const staticData = $getWorkflowStaticData('global');
const results = staticData.results || [];
const setup = $('Setup').first().json;
const projectId = setup.input.project_id;

// Groepeer resultaten per level
const gebouwen = results.filter(r => r.level === 'gebouw');
const verdiepen = results.filter(r => r.level === 'verdiep');
const collectoren = results.filter(r => r.level === 'collector');
const kringen = results.filter(r => r.level === 'kring');

// Bouw geneste structuur op
const output = gebouwen.map(g => ({
  odoo_id: g.odooId,
  naam: g.meta.naam,
  verdiepen: verdiepen
    .filter(v => v.meta.gi === g.meta.gi)
    .map(v => ({
      odoo_id: v.odooId,
      nummer: v.meta.nummer,
      collectoren: collectoren
        .filter(c => c.meta.gi === g.meta.gi && c.meta.vi === v.meta.vi)
        .map(c => ({
          odoo_id: c.odooId,
          nummer: c.meta.nummer,
          kringen: kringen
            .filter(k => k.meta.gi === g.meta.gi && k.meta.vi === v.meta.vi && k.meta.ci === c.meta.ci)
            .map(k => ({
              odoo_id: k.odooId,
              nummer: k.meta.nummer
            }))
        }))
    }))
}));

// Ruim static data op
delete staticData.idMap;
delete staticData.stageMap;
delete staticData.results;

return [{
  json: {
    success: true,
    project_id: projectId,
    gebouwen: output
  }
}];
